import { consultarEstacionService } from './service.mjs';

export async function handler(event) {
  const estacionId = Number(event.pathParameters.estacionId);
  const minimo = Number(event.queryStringParameters?.minimo ?? 0);
  const resultado = await consultarEstacionService(estacionId, minimo);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { buscarEstacionRepository, consultarEstacionRepository } from './repository.mjs';

export async function consultarEstacionService(estacionId, minimo) {
  const estacion = await buscarEstacionRepository(estacionId);
  if (!estacion) throw new Error('Estacion no encontrado');
  const trayectos = await consultarEstacionRepository(estacionId, minimo);
  return { estacion, trayectos };
}

import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_TRAYECTO, MODELO_ESTACION } from '../../models/estacion-trayecto.model.mjs';

export async function buscarEstacionRepository(estacionId) {
  const { Item } = await MODELO_ESTACION.build(EntityRepository).get(
    { estacionId },
    { consistent: true }
  );
  return Item ?? null;
}

export async function consultarEstacionRepository(estacionId, minimo) {
  const { Items = [] } = await MODELO_TRAYECTO.build(EntityRepository).query(
    { index: 'PorEstacion', partition: estacionId },
    { filters: { Trayecto: { attr: 'distanciaKm', gte: minimo } } }
  );
  return Items;
}

